declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';if(PHP_SAPI!=='cli')exit(1);$c=require dirname(__DIR__).'/config/main.php';if(($c['database']??'')!=='hls_v2')throw new RuntimeException('Target bukan hls_v2');$db=Hls\Database::connect($c);$tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$counts=[];foreach($tables as $t)$counts[$t]=(int)$db->query('SELECT COUNT(*) FROM `'.$t.'`')->fetchColumn();$checks=['tables'=>count($tables),'users'=>$counts['users']??0,'roles'=>$counts['roles']??0,'permissions'=>$counts['permissions']??0,'role_permissions'=>$counts['role_permissions']??0,'branches'=>$counts['branches']??0,'master_rows'=>array_sum(array_intersect_key($counts,array_flip(['md_customers','md_parties','md_locations','md_routes','md_assets','md_personnel','md_categories','md_units','md_items']))),'transactions'=>array_sum(array_intersect_key($counts,array_flip(['exp_dns','exp_manifests','exp_receipts','exp_claims','eq_contracts','eq_handover_documents','eq_timesheets']))),'c_permissions'=>(int)$db->query("SELECT COUNT(*) FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE p.code IN ('equipment.handover.correct','equipment.handover.fact_correct','equipment.cross_branch.approve','equipment.recovery.close','equipment.meter.correct','equipment.timesheet.revise_terminal','equipment.operator.relink')")->fetchColumn()];file_put_contents(dirname(__DIR__).'/storage/private/backups/main-verification.json',json_encode(['database'=>'hls_v2','verified_at'=>date(DATE_ATOM),'checks'=>$checks,'counts'=>$counts],JSON_PRETTY_PRINT));echo json_encode($checks,JSON_PRETTY_PRINT).PHP_EOL;
